import shutil, re, openpyxl

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def norm(x):
    if x is None:
        return ''
    s = str(x).strip().upper()
    s = re.sub(r'\s+', ' ', s)
    return s

# ensure Total
if 'Total' not in wb.sheetnames:
    ws = wb.create_sheet('Total')
else:
    ws = wb['Total']
vws = vals['Total'] if 'Total' in vals.sheetnames else None

# month standard
month_prefixes = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC']
month_full = ['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER']
std_sheets = []
for p in month_prefixes:
    found = None
    for sn in vals.sheetnames:
        n = norm(sn)
        if n == p or n.startswith(p):
            found = sn
            break
    std_sheets.append(found if found else p)

alias_map = {}
for i,p in enumerate(month_prefixes):
    alias_map[p] = std_sheets[i]
    alias_map[month_full[i]] = std_sheets[i]
    alias_map[str(i+1)] = std_sheets[i]

def map_month_header(h):
    n = norm(h)
    if not n:
        return None
    if n in alias_map:
        return alias_map[n]
    # try longest alias prefix
    for a in sorted(alias_map.keys(), key=len, reverse=True):
        if n.startswith(a):
            return alias_map[a]
    return None

month_names = []
for col in range(15, 27):
    found = None
    if vws is not None:
        for row in range(1, 5):
            h = vws.cell(row=row, column=col).value
            m = map_month_header(h)
            if m:
                found = m
                break
    if not found:
        found = std_sheets[col-15]
    # ensure exists, else fallback
    if found not in vals.sheetnames:
        # try by index
        found = std_sheets[col-15] if col-15 < len(std_sheets) else None
    month_names.append(found)

# names from Jan or first month
base_sheet = None
for sn in ['Jan', std_sheets[0]]:
    if sn in vals.sheetnames:
        base_sheet = sn
        break
if base_sheet is None:
    base_sheet = vals.sheetnames[0]
base_vws = vals[base_sheet]

name_to_row = {}
names_order = []
for r in range(6, base_vws.max_row + 1):
    n = norm(base_vws.cell(row=r, column=1).value)
    if n and n not in name_to_row:
        name_to_row[n] = r
        names_order.append(n)

codes = ['P','ODK','A','L','WO','PH','CO','ML']
code_aliases = {
 'PRESENT':'P', 'ABSENT':'A', 'LEAVE':'L', 'WEEKLY OFF':'WO', 'PUBLIC HOLIDAY':'PH', 'COMP OFF':'CO', 'COMP. OFF':'CO', 'MEDICAL LEAVE':'ML', 'WORK AT KARAI':'ODK'
}
def match_code(label):
    n = norm(label)
    if not n:
        return None
    if n in codes:
        return n
    if n in code_aliases:
        return code_aliases[n]
    for code in codes:
        if n.startswith(code):
            if len(n) == len(code):
                return code
            nxt = n[len(code)]
            if nxt in ' -:/(':
                return code
    # alias startswith
    for a, c in code_aliases.items():
        if n.startswith(a):
            return c
    return None

# get labels
def get_label(r):
    if vws is None:
        return ''
    for c in [14, 13, 12, 11, 10]:
        v = vws.cell(row=r, column=c).value
        if v is not None and str(v).strip():
            return norm(v)
    return ''

labels = [get_label(r) for r in range(5, 13)]
code_labels = [match_code(l) for l in labels]
name_labels = [l if l in name_to_row else None for l in labels]
code_count = sum(1 for c in code_labels if c)
name_count = sum(1 for n in name_labels if n)
mode = 'codes'
if name_count >= 4 and name_count > code_count:
    mode = 'names'

if mode == 'codes':
    row_codes = []
    for i, c in enumerate(code_labels):
        if c:
            row_codes.append(c)
        else:
            row_codes.append(codes[i] if i < len(codes) else 'P')
    person = ''
    if vws is not None:
        person = norm(vws['O3'].value)
    if not person:
        person = norm(ws['O3'].value)
    if not person and names_order:
        person = names_order[0]
    person_row = name_to_row.get(person)
    if person_row is None:
        # try fuzzy
        for n, r in name_to_row.items():
            if person and (n.startswith(person) or person.startswith(n)):
                person_row = r
                break
    if person_row is None and names_order:
        person_row = name_to_row[names_order[0]]
else:
    row_names = []
    for i, n in enumerate(name_labels):
        if n:
            row_names.append(n)
        else:
            row_names.append(names_order[i] if i < len(names_order) else '')

# divide inference from formulas only
divide = True
formula_hint = None
for row in ws.iter_rows(min_row=5, max_row=12, min_col=15, max_col=26):
    for cell in row:
        v = cell.value
        if isinstance(v, str) and v.startswith('='):
            if re.search(r'/\s*2\b', v):
                formula_hint = True
            elif re.search(r'(SUMIFS|COUNTIFS|SUMPRODUCT)', v, re.I):
                if formula_hint is None:
                    formula_hint = False
if formula_hint is True:
    divide = True
elif formula_hint is False:
    # If there are explicit formulas without /2, maybe they intend raw counts.
    # But to preserve day semantics, only switch if no /2 and formula uses SUMIFS/COUNTIFS? Hmm.
    # Let's not switch? If formula_hint False, maybe user's formula. Default divide True.
    divide = True
# Actually if formula_hint False, keep True. So formula_hint only matters if True.
